SELECT mail_template_id::TEXT AS row_id, template_cd, name, subject, variables, use_yn, upd_dt FROM mail_template WHERE use_yn = 'Y'
AND (name LIKE '%' || #{filterKeyword} || '%' OR template_cd LIKE '%' || #{filterKeyword} || '%')
ORDER BY template_cd LIMIT #{pageSize} OFFSET #{offset}
